import rclpy
import os
from ament_index_python import get_package_share_directory, get_package_prefix
import pathlib
version = "dev"
release_date = "xxx"


def get_package_path():
    """获取 ROS 包的路径"""
    try:
        # 获取包的 share 目录路径（安装后）
        share_dir = get_package_share_directory('tools')
        return share_dir
    except Exception:
        # 如果无法获取 share 目录，则尝试获取包的安装前缀
        try:
            prefix = get_package_prefix('tools')
            return prefix
        except Exception:
            # 如果都失败，返回当前文件的包目录路径（开发时）
            current_file = os.path.abspath(__file__)
            package_path = os.path.dirname(os.path.dirname(current_file))
            return package_path


def main(args=None):
    package_path = get_package_path()
    parent_dir = pathlib.Path(package_path).parent.parent.parent.parent
    print(f"parent directory: {parent_dir}")
    version_file = parent_dir / "VERSION"
    if not version_file.exists():
        print(f"VERSION file not found in {parent_dir}, this is a development version")
        return
    with open(version_file, "r") as f:
        version = f.read().strip()
    print(f"version: {version}")
    # 查看文件创建时间
    try:
        stat = os.stat(version_file)
        if hasattr(stat, 'st_ctime'):
            create_time = stat.st_ctime
            import datetime
            create_time_str = datetime.datetime.fromtimestamp(create_time).strftime('%Y-%m-%d %H:%M:%S')
            release_date = create_time_str
            print(f"release date: {release_date}")
        else:
            print("Cannot retrieve file creation time on this OS.")
    except Exception as e:
        print(f"Failed to obtain VERSION file creation time: {e}")
    


if __name__ == '__main__':
    main()
